import{_ as a,C as c,o as l,c as s,j as r,a as d,E as t,a2 as i}from"./chunks/framework.BxGh02fV.js";const q=JSON.parse('{"title":"Boucle équipe","description":"","frontmatter":{"title":"Boucle équipe"},"headers":[],"relativePath":"agent/boucle-equipe.md","filePath":"agent/boucle-equipe.md"}'),u={name:"agent/boucle-equipe.md"};function n(p,e,f,m,h,b){const o=c("Ask");return l(),s("div",null,[e[0]||(e[0]=r("h1",{id:"boucle-equipe",tabindex:"-1"},[d("Boucle équipe "),r("a",{class:"header-anchor",href:"#boucle-equipe","aria-label":'Permalink to "Boucle équipe"'},"​")],-1)),e[1]||(e[1]=r("p",null,"Ce parcours sert à faire avancer une story, un épic ou un atelier d'évolutions par une boucle à trois rôles : un analyste, un développeur senior et un ingénieur QA se relaient sur le pipe OPALE. Vous y venez quand vous voulez que l'agent enchaîne le travail au lieu de le conduire pas à pas.",-1)),e[2]||(e[2]=r("p",null,"Le moteur n'exécute aucun agent lui-même : il rend le contrat de l'acte suivant, votre agent l'exécute (avec un sous-agent s'il en a), puis rapporte le résultat.",-1)),e[3]||(e[3]=r("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[d("Ce que vous demandez à l'agent "),r("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),t(o,{say:"Lance la boucle équipe sur l'épic courant.",verb:"effortless_crew_init",family:"boucle-equipe",args:'{"goal":"l’épic courant"}'}),t(o,{say:"Fais tourner l'équipe sur cette story seulement, avec pnpm test et pnpm lint comme barre.",verb:"effortless_crew_init",family:"boucle-equipe",args:'{"goal":"cette story","bar":{"test":"pnpm test","lint":"pnpm lint"}}'}),t(o,{say:"Où en est la boucle ? Qui doit agir maintenant ?",verb:"effortless_crew_status",family:"boucle-equipe"}),t(o,{say:"Montre-moi la trace complète de ce qui s'est passé dans la boucle.",verb:"effortless_crew_status",family:"boucle-equipe",args:'{"full":true}'}),t(o,{say:"Classe la tâche TSK-03 en complexe, palier profond, effort élevé, et dis-moi quel modèle ça donne.",verb:"effortless_task_classify",family:"boucle-equipe",args:'{"task_id":"TSK-03","complexity":"complex","capability_tier":"deep","effort_level":"high"}'}),t(o,{say:"Génère un profil de fournisseurs à partir du preset claude, pour ce projet seulement.",verb:"effortless_provider_profile_init",family:"boucle-equipe",args:'{"family":"claude","scope":"project"}'}),t(o,{say:"Montre-moi les presets de fournisseurs disponibles et mon profil actuel.",verb:"effortless_provider_presets_list",family:"boucle-equipe"}),t(o,{say:"Lance la boucle autonome sur les tâches simples du backlog.",verb:"effortless_loop_init",family:"boucle-equipe",args:'{"goal":"les tâches simples du backlog"}'}),e[4]||(e[4]=i('<h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="demarrer-la-boucle-equipe" tabindex="-1">Démarrer la boucle équipe <a class="header-anchor" href="#demarrer-la-boucle-equipe" aria-label="Permalink to &quot;Démarrer la boucle équipe&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/boucle-equipe.html#crew-init"><code>effortless_crew_init</code></a> reçoit <code>goal</code> (l&#39;objectif, repris dans chaque consigne de rôle) et <code>scope</code> : <code>story</code>, <code>epic</code> (défaut), <code>all</code> ou <code>workshop</code>. <code>max_rounds</code> (100 par défaut) et <code>max_epics</code> (3 par défaut) plafonnent la boucle ; <code>0</code> veut dire illimité.</li><li><code>bar</code> déclare la barre mécanique : un objet qui associe un nom (<code>test</code>, <code>lint</code>, <code>typecheck</code>, <code>build</code>) à une commande, ou à un objet avec <code>command</code> et éventuellement <code>cwd</code> ou <code>stack</code>. Il faut au moins une commande, et elle doit pouvoir s&#39;exécuter : une commande non mesurée ne serait jamais verte et le QA ne pourrait jamais rendre <code>go</code>.</li><li><code>force: true</code> écrase une boucle déjà initialisée.</li><li>En périmètre <code>all</code>, quand il n&#39;y a plus d&#39;épic à livrer, la boucle entre dans l&#39;atelier d&#39;évolutions et gradue un axe en épic suivant, jusqu&#39;à <code>max_epics</code>.</li></ol><h3 id="faire-un-tour-de-boucle" tabindex="-1">Faire un tour de boucle <a class="header-anchor" href="#faire-un-tour-de-boucle" aria-label="Permalink to &quot;Faire un tour de boucle&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/boucle-equipe.html#crew-step"><code>effortless_crew_step</code></a> rend le contrat de l&#39;acte courant : le rôle qui doit agir, le modèle et l&#39;effort recommandés, la sortie attendue, et <code>prompt_path</code>, le chemin d&#39;un fichier qui contient la consigne (une clé <code>prompt</code>). L&#39;agent lit ce fichier avant de lancer le sous-agent. Appelé deux fois, <code>effortless_crew_step</code> rend deux fois la même chose : il n&#39;avance rien. <code>document</code> vise un document de cadrage précis.</li><li>Le rôle exécute l&#39;acte.</li><li><a href="/Effortless/reference/mcp/boucle-equipe.html#crew-report"><code>effortless_crew_report</code></a> rapporte le résultat : <code>role</code> (<code>analyst</code>, <code>developer</code> ou <code>qa</code>, celui que l&#39;étape attend), <code>verdict</code> (<code>done</code> pour l&#39;analyste et le développeur, <code>go</code> ou <code>no-go</code> pour le QA), <code>summary</code>, et <code>payload</code> (la sortie structurée du rôle). Pour une charge trop volumineuse, <code>payload_path</code> désigne un fichier JSON à la place, jamais les deux.</li><li><code>effortless_crew_report</code> mesure la barre mécanique avant de rendre la main ; l&#39;appel peut être long. Il rend directement l&#39;acte suivant.</li><li>À la livraison, le moteur commite lui-même le travail de la tâche, puis la clôture. Il répète le tour jusqu&#39;à ce que le périmètre soit couvert ou qu&#39;un plafond soit atteint. Trois <code>no-go</code> de suite arrêtent la boucle.</li></ol><h3 id="suivre-la-boucle" tabindex="-1">Suivre la boucle <a class="header-anchor" href="#suivre-la-boucle" aria-label="Permalink to &quot;Suivre la boucle&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/boucle-equipe.html#crew-status"><code>effortless_crew_status</code></a> lit l&#39;état sans rien changer : étape, rôle attendu, pointeur épic / story / tâche, compteurs, plafonds, raison de fin (<code>scope_covered</code>, <code>epics_exhausted</code> ou <code>rounds_exhausted</code>, <code>null</code> tant que la boucle tourne) et ledger daté des actes. Par défaut, seuls les derniers actes sont rendus ; <code>full: true</code> rend la trace complète.</li></ol><h3 id="router-une-tache-vers-un-palier-de-modele" tabindex="-1">Router une tâche vers un palier de modèle <a class="header-anchor" href="#router-une-tache-vers-un-palier-de-modele" aria-label="Permalink to &quot;Router une tâche vers un palier de modèle&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/boucle-equipe.html#task-classify"><code>effortless_task_classify</code></a> classe une tâche de la story active sur un ou plusieurs axes : <code>complexity</code> (<code>simple</code> ou <code>complex</code>), <code>capability_tier</code> (<code>deep</code>, <code>standard</code> ou <code>light</code>), <code>effort_level</code> (<code>low</code>, <code>medium</code> ou <code>high</code>). Il en faut au moins un ; un axe absent reste inchangé.</li><li><a href="/Effortless/reference/mcp/boucle-equipe.html#task-route-show"><code>effortless_task_route_show</code></a> rend la recommandation résolue : palier et effort, traduits en modèle concret et en effort natif par votre profil de fournisseurs (profil du projet d&#39;abord, puis profil global). Sans classement, le défaut est <code>standard</code> / <code>medium</code>. C&#39;est une suggestion, jamais une obligation.</li></ol><h3 id="regler-les-fournisseurs" tabindex="-1">Régler les fournisseurs <a class="header-anchor" href="#regler-les-fournisseurs" aria-label="Permalink to &quot;Régler les fournisseurs&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/boucle-equipe.html#provider-presets-list"><code>effortless_provider_presets_list</code></a> liste les presets embarqués et personnalisés.</li><li><a href="/Effortless/reference/mcp/boucle-equipe.html#provider-profile-show"><code>effortless_provider_profile_show</code></a> lit votre profil actif.</li><li><a href="/Effortless/reference/mcp/boucle-equipe.html#provider-profile-init"><code>effortless_provider_profile_init</code></a> (re)génère le profil, une matrice palier × effort, depuis une famille de preset : <code>claude</code>, <code>codex</code>, <code>gemini</code>, <code>mistral</code> ou un nom libre. <code>scope</code> vaut <code>global</code> (défaut) ou <code>project</code>. Un profil existant n&#39;est écrasé qu&#39;avec <code>force: true</code>.</li></ol><h3 id="la-boucle-autonome" tabindex="-1">La boucle autonome <a class="header-anchor" href="#la-boucle-autonome" aria-label="Permalink to &quot;La boucle autonome&quot;">​</a></h3><p>C&#39;est une boucle plus simple, qui prend les tâches du backlog une à une.</p><ol><li><a href="/Effortless/reference/mcp/boucle-equipe.html#loop-init"><code>effortless_loop_init</code></a> la démarre avec un <code>goal</code>.</li><li><a href="/Effortless/reference/mcp/boucle-equipe.html#loop-step"><code>effortless_loop_step</code></a> la fait avancer : Plan, Implémentation, Recette, Livraison. À la recette, elle joue <code>test_command</code> (par défaut, le cycle de test du modèle de la première stack). Une tâche non classée doit d&#39;abord l&#39;être, une tâche complexe se décompose en tâches simples. Quand les tests passent, la boucle tente de commiter la tâche. Après trop d&#39;échecs de recette, elle s&#39;arrête.</li></ol><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><ul><li>Le travail avance tâche après tâche, avec un commit de livraison par tâche et une clôture quand l&#39;épic est fini.</li><li>Un état de boucle et un ledger horodaté, relisibles à tout moment par <code>effortless_crew_status</code>.</li><li>Dans l&#39;app, vous suivez la progression dans <a href="/Effortless/guide/tasks.html">Tâches</a>, <a href="/Effortless/guide/backlog.html">Backlog</a> et <a href="/Effortless/guide/dashboard.html">Tableau de bord</a>.</li><li>Un profil de fournisseurs dans votre dossier personnel (profil global) ou dans le projet (profil projet).</li></ul><h2 id="quand-l-agent-est-refuse" tabindex="-1">Quand l&#39;agent est refusé <a class="header-anchor" href="#quand-l-agent-est-refuse" aria-label="Permalink to &quot;Quand l&#39;agent est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Ce que dit le refus</th><th>Ce qu&#39;il faut faire</th></tr></thead><tbody><tr><td>Le projet est en mode semi-auto</td><td>Message « outil d&#39;exécution désactivé », marqué <code>gated</code>, pour <code>crew_init</code>, <code>crew_step</code>, <code>crew_report</code>, <code>loop_init</code>, <code>loop_step</code></td><td>Passer le projet en mode full.</td></tr><tr><td>Périmètre inconnu</td><td><code>crew:scopeInvalid</code></td><td>Passer <code>scope</code> parmi <code>story</code>, <code>epic</code>, <code>all</code>, <code>workshop</code>.</td></tr><tr><td>Aucun épic actif</td><td><code>crew:noActiveEpic</code></td><td>Activer un épic avec <code>effortless_epic_activate</code>, ou relancer avec <code>scope: &quot;workshop&quot;</code>.</td></tr><tr><td>Une boucle existe déjà</td><td><code>crew:alreadyInitialized</code></td><td>Passer <code>force: true</code> pour l&#39;écraser.</td></tr><tr><td>Aucune commande de barre</td><td><code>crew:barMissing</code></td><td>Passer <code>bar</code>, par exemple <code>{&quot;test&quot;: &quot;…&quot;, &quot;lint&quot;: &quot;…&quot;}</code>.</td></tr><tr><td>La barre ne peut pas s&#39;exécuter</td><td><code>crew:barUnrunnable</code>, qui nomme l&#39;exécutable fautif</td><td>Corriger les commandes nommées dans <code>bar</code>, puis relancer.</td></tr><tr><td><code>cwd</code> de la barre absolu ou hors du projet</td><td><code>crew:barCwdInvalid</code></td><td>Relancer <code>effortless_crew_init</code> avec un <code>bar.cwd</code> relatif à la racine du projet.</td></tr><tr><td>Chemin d&#39;une stack introuvable</td><td><code>crew:stackPathMissing</code></td><td>Créer l&#39;arborescence nommée, ou corriger le <code>path</code> de la stack avec <code>effortless_stack_add</code>.</td></tr><tr><td>Aucune boucle initialisée</td><td><code>crew:notInitialized</code></td><td>Lancer <code>effortless_crew_init</code>.</td></tr><tr><td>Rôle ou verdict inconnu</td><td><code>crew:roleUnknown</code> ou <code>crew:verdictUnknown</code></td><td>Passer <code>role</code> parmi <code>analyst</code>, <code>developer</code>, <code>qa</code> ; <code>verdict</code> parmi <code>go</code>, <code>no-go</code>, <code>done</code>.</td></tr><tr><td>Le rôle rapporté n&#39;est pas celui attendu</td><td><code>crew:roleMismatch</code></td><td>Rapporter avec le rôle attendu ; <code>effortless_crew_step</code> le nomme.</td></tr><tr><td>Rapport sur une étape sans acteur</td><td><code>crew:stageHasNoActor</code></td><td>Appeler <code>effortless_crew_step</code> pour connaître l&#39;acte réellement attendu.</td></tr><tr><td><code>payload</code> et <code>payload_path</code> ensemble</td><td><code>crew:payloadPathEtPayload</code></td><td>N&#39;en fournir qu&#39;un des deux.</td></tr><tr><td><code>payload_path</code> introuvable, hors du projet, trop gros ou mal formé</td><td><code>crew:payloadPathIntrouvable</code>, <code>crew:payloadPathHorsPerimetre</code>, <code>crew:payloadPathTropGros</code>, <code>crew:payloadPathJsonInvalide</code>, <code>crew:payloadPathRacineNonObjet</code></td><td>Pointer un fichier JSON du projet dont la racine est un objet (4 Mio au plus).</td></tr><tr><td>Code déclaré absent de la branche</td><td><code>crew:filesNotIntegrated</code></td><td>Lancer <code>effortless_worktree_reintegrate</code> depuis le worktree qui porte le travail, puis relancer le rapport.</td></tr><tr><td>Le commit de livraison est refusé</td><td><code>crew:commitRefused</code></td><td>Lever la cause que git nomme dans le refus, puis relancer le rapport.</td></tr><tr><td>Livraison interrompue, rapport d&#39;un autre rôle</td><td><code>crew:deliveryResumeRequiresQaGo</code></td><td>Reprendre par le rapport <code>qa</code> / <code>go</code> qui a pu l&#39;amorcer.</td></tr><tr><td>Profil de fournisseurs déjà présent</td><td><code>create:providerExists</code></td><td>Passer <code>force: true</code> pour l&#39;écraser.</td></tr><tr><td>Portée de profil invalide</td><td><code>common:scopeInvalid</code></td><td>Passer <code>scope</code> à <code>global</code> ou <code>project</code>.</td></tr><tr><td>Profil de projet sans projet</td><td><code>common:projectNotInitialized</code></td><td>Initialiser le projet, ou viser la portée <code>global</code>.</td></tr></tbody></table>',18))])}const _=a(u,[["render",n]]);export{q as __pageData,_ as default};
